```c
/* k13_conv2d: 2-D convolution of an image with a 15x15 filter (valid region).
 * UNIFORM cost per output pixel, compute-bound: the core of CNN layers. */
#include "common.h"
#include <omp.h>

#define KS 15

/* === KERNEL BEGIN === */
static void kernel(int h, int w, const float *img, const float *filt, float *out) {
    int oh = h - KS + 1, ow = w - KS + 1;

    /* Use collapse(2) to merge the y and x loops into a single iteration space,
     * providing better granularity for load balancing across the different 
     * core types (P-cores and E-cores) of the Apple M4.
     * schedule(guided) is used to balance the load between the fast P-cores 
     * and the slower E-cores, starting with large chunks and decreasing them 
     * as the work progresses to minimize overhead while ensuring all cores 
     * finish at roughly the same time. */
    #pragma omp parallel for collapse(2) schedule(guided)
    for (int y = 0; y < oh; y++) {
        for (int x = 0; x < ow; x++) {
            float s = 0.0f;
            for (int ky = 0; ky < KS; ky++) {
                /* Pre-calculate row pointers to help the compiler vectorize 
                 * the innermost loop. The filter is small enough to fit in L1. */
                const float *img_row = &img[(long)(y + ky) * w + x];
                const float *filt_row = &filt[ky * KS];
                for (int kx = 0; kx < KS; kx++) {
                    s += img_row[kx] * filt_row[kx];
                }
            }
            out[(long)y * ow + x] = s;
        }
    }
}
/* === KERNEL END === */

int main(int argc, char **argv) {
    int h = (int)arg_long(argc, argv, 1, 6144), w = (int)arg_long(argc, argv, 2, 6144);
    long oh = h - KS + 1, ow = w - KS + 1;
    float *img = xmalloc((long)h * w * sizeof *img), filt[KS * KS];
    float *out = xmalloc(oh * ow * sizeof *out);
    rng_seed(13);
    for (long k = 0; k < (long)h * w; k++) img[k] = (float)rng_unit();
    for (int k = 0; k < KS * KS; k++) filt[k] = (float)rng_unit() / (KS * KS);

    double t0 = now_sec();
    kernel(h, w, img, filt, out);
    double t1 = now_sec();

    double sum = 0.0;   /* each pixel is computed in a fixed order: exact */
    for (long k = 0; k < oh * ow; k++) sum += out[k];
    report("conv2d", t1 - t0, sum);
    free(img); free(out);
    return 0;
}
